def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    if not cells:
        return {}

    def cell_index(name: str) -> int:
        return (int(name[1:]) - 1) * 26 + (ord(name[0]) - 65)

    def tokenize(s: str) -> list[tuple[str, object]]:
        tokens: list[tuple[str, object]] = []
        n = len(s)
        i = 0
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
            elif "0" <= ch <= "9":
                j = i + 1
                while j < n and "0" <= s[j] <= "9":
                    j += 1
                tokens.append(("NUM", int(s[i:j])))
                i = j
            elif "A" <= ch <= "Z":
                j = i + 1
                while j < n and "A" <= s[j] <= "Z":
                    j += 1
                if j < n and "0" <= s[j] <= "9":
                    k = j + 1
                    while k < n and "0" <= s[k] <= "9":
                        k += 1
                    tokens.append(("CELL", (int(s[j:k]) - 1) * 26 + (ord(s[i]) - 65)))
                    i = k
                else:
                    tokens.append(("ID", s[i:j]))
                    i = j
            elif ch == "<" or ch == ">":
                if i + 1 < n and (s[i + 1] == "=" or (ch == "<" and s[i + 1] == ">")):
                    tokens.append(("OP", s[i : i + 2]))
                    i += 2
                else:
                    tokens.append(("OP", ch))
                    i += 1
            elif ch == "=":
                tokens.append(("OP", "="))
                i += 1
            else:
                tokens.append((ch, ch))
                i += 1
        tokens.append(("EOF", ""))
        return tokens

    def parse(expr: str) -> tuple:
        tokens = tokenize(expr)
        pos = 0

        def parse_formula() -> tuple:
            nonlocal pos
            node = parse_term()
            while tokens[pos][0] in ("+", "-"):
                op = tokens[pos][0]
                pos += 1
                right = parse_term()
                node = ("BIN", op, node, right)
            return node

        def parse_term() -> tuple:
            nonlocal pos
            node = parse_unary()
            while tokens[pos][0] in ("*", "/"):
                op = tokens[pos][0]
                pos += 1
                right = parse_unary()
                node = ("BIN", op, node, right)
            return node

        def parse_unary() -> tuple:
            nonlocal pos
            neg_count = 0
            while tokens[pos][0] == "-":
                neg_count += 1
                pos += 1
            node = parse_atom()
            if neg_count & 1:
                node = ("NEG", node)
            return node

        def parse_atom() -> tuple:
            nonlocal pos
            tok = tokens[pos]
            kind = tok[0]
            if kind == "NUM":
                pos += 1
                return ("NUM", tok[1])
            if kind == "CELL":
                pos += 1
                return ("CELL", tok[1])
            if kind == "(":
                pos += 1
                node = parse_formula()
                pos += 1
                return node
            fn = tok[1]
            pos += 2
            if fn == "IF":
                left = parse_formula()
                op = tokens[pos][1]
                pos += 1
                right = parse_formula()
                pos += 1
                then_n = parse_formula()
                pos += 1
                else_n = parse_formula()
                pos += 1
                return ("IF", op, left, right, then_n, else_n)
            args = []
            while True:
                if tokens[pos][0] == "CELL" and tokens[pos + 1][0] == ":":
                    r1, c1 = divmod(tokens[pos][1], 26)
                    r2, c2 = divmod(tokens[pos + 2][1], 26)
                    pos += 3
                    if r1 > r2:
                        r1, r2 = r2, r1
                    if c1 > c2:
                        c1, c2 = c2, c1
                    args.append(("RANGE", r1, r2, c1, c2))
                else:
                    args.append(parse_formula())
                if tokens[pos][0] == ",":
                    pos += 1
                else:
                    break
            pos += 1
            return ("AGG", fn, args)

        return parse_formula()

    # state: 0 = missing, 1 = unvisited formula, 2 = in progress, 3 = evaluated
    state = [0] * 2574
    values: list[int | str] = [0] * 2574
    asts: list[tuple | None] = [None] * 2574
    name_to_idx: dict[str, int] = {}

    for name, raw in cells.items():
        idx = cell_index(name)
        name_to_idx[name] = idx
        s = raw.strip()
        if s.startswith("="):
            asts[idx] = parse(s[1:])
            state[idx] = 1
        else:
            values[idx] = int(s)
            state[idx] = 3

    for root_idx in name_to_idx.values():
        if state[root_idx] != 1:
            continue

        state[root_idx] = 2
        stack: list[tuple] = [("CELL_DONE", root_idx)]
        node: tuple | None = asts[root_idx]
        agg_state: tuple | None = None
        val: int | str = 0

        while True:
            if node is not None:
                kind = node[0]
                if kind == "NUM":
                    val = node[1]
                    node = None
                elif kind == "CELL":
                    cidx = node[1]
                    st = state[cidx]
                    if st == 0:
                        val = 0
                        node = None
                    elif st == 3:
                        val = values[cidx]
                        node = None
                    elif st == 2:
                        val = "#CYCLE!"
                        node = None
                    else:
                        state[cidx] = 2
                        stack.append(("CELL_DONE", cidx))
                        node = asts[cidx]
                elif kind == "NEG":
                    stack.append(("NEG",))
                    node = node[1]
                elif kind == "BIN":
                    stack.append(("BIN_L", node[1], node[3]))
                    node = node[2]
                elif kind == "IF":
                    stack.append(("IF_L", node[1], node[3], node[4], node[5]))
                    node = node[2]
                else:  # "AGG"
                    fn = node[1]
                    agg_state = (fn, node[2], 0, -1, 0, 0 if fn == "SUM" else None)
                    node = None
            elif agg_state is not None:
                fn, args, arg_idx, r, c, acc = agg_state
                agg_state = None
                while arg_idx < len(args):
                    arg = args[arg_idx]
                    if arg[0] == "RANGE":
                        _, r1, r2, c1, c2 = arg
                        if r == -1:
                            r, c = r1, c1
                        need_eval = False
                        while r <= r2:
                            cidx = r * 26 + c
                            c += 1
                            if c > c2:
                                c = c1
                                r += 1
                            st = state[cidx]
                            if st == 0:
                                continue
                            if st == 3:
                                v = values[cidx]
                                if isinstance(v, str):
                                    val = v
                                    need_eval = True
                                    break
                                if fn == "SUM":
                                    acc += v
                                elif fn == "MIN":
                                    if acc is None or v < acc:
                                        acc = v
                                else:
                                    if acc is None or v > acc:
                                        acc = v
                            elif st == 2:
                                val = "#CYCLE!"
                                need_eval = True
                                break
                            else:
                                next_arg_idx = arg_idx + 1 if r > r2 else arg_idx
                                next_r = -1 if r > r2 else r
                                state[cidx] = 2
                                stack.append(("AGG_WAIT", fn, args, next_arg_idx, next_r, c, acc))
                                stack.append(("CELL_DONE", cidx))
                                node = asts[cidx]
                                need_eval = True
                                break
                        if need_eval:
                            break
                        arg_idx += 1
                        r = -1
                    else:
                        stack.append(("AGG_WAIT", fn, args, arg_idx + 1, -1, 0, acc))
                        node = arg
                        break
                else:
                    val = 0 if acc is None else acc
            else:
                if not stack:
                    break
                frame = stack.pop()
                fk = frame[0]
                if fk == "CELL_DONE":
                    cidx = frame[1]
                    values[cidx] = val
                    state[cidx] = 3
                elif fk == "NEG":
                    if not isinstance(val, str):
                        val = -val
                elif fk == "BIN_L":
                    if not isinstance(val, str):
                        stack.append(("BIN_R", frame[1], val))
                        node = frame[2]
                elif fk == "BIN_R":
                    if not isinstance(val, str):
                        op, lval = frame[1], frame[2]
                        if op == "+":
                            val = lval + val
                        elif op == "-":
                            val = lval - val
                        elif op == "*":
                            val = lval * val
                        else:
                            if val == 0:
                                val = "#DIV/0!"
                            else:
                                q = abs(lval) // abs(val)
                                val = -q if (lval < 0) ^ (val < 0) else q
                elif fk == "IF_L":
                    if not isinstance(val, str):
                        stack.append(("IF_R", frame[1], val, frame[3], frame[4]))
                        node = frame[2]
                elif fk == "IF_R":
                    if not isinstance(val, str):
                        op, lval, then_n, else_n = frame[1], frame[2], frame[3], frame[4]
                        if op == "=":
                            cond = lval == val
                        elif op == "<>":
                            cond = lval != val
                        elif op == "<":
                            cond = lval < val
                        elif op == "<=":
                            cond = lval <= val
                        elif op == ">":
                            cond = lval > val
                        else:
                            cond = lval >= val
                        node = then_n if cond else else_n
                else:  # "AGG_WAIT"
                    if not isinstance(val, str):
                        _, fn, args, arg_idx, r, c, acc = frame
                        if fn == "SUM":
                            acc += val
                        elif fn == "MIN":
                            if acc is None or val < acc:
                                acc = val
                        else:
                            if acc is None or val > acc:
                                acc = val
                        agg_state = (fn, args, arg_idx, r, c, acc)

    return {name: values[idx] for name, idx in name_to_idx.items()}
